/**
 * A plan change ends the trial: the org has made a deliberate choice.
 * The subscription row is the authority, and `organizations.plan` is kept
 * in step so a denormalised read cannot keep serving the previous plan.
 * The org row is untouched when this subscription does not exist.
 */
export async function updateSubscriptionPlan(
  orgId: OrgId,
  plan: PlanId,
  interval: BillingInterval,
): Promise<Subscription> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb().transaction((tx) => {
    const updated = tx
      .update(subscriptions)
      .set({ plan, interval, status: "active", updatedAt: stamp })
      .where(orgPredicate(subscriptions.orgId, orgId))
      .returning()
      .get();

    if (!updated) return undefined;

    tx.update(organizations)
      .set({ plan, updatedAt: stamp })
      .where(and(eq(organizations.id, orgId), ne(organizations.plan, plan)))
      .run();

    return updated;
  });

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

