/**
 * Subscription plan when the workspace has one, otherwise the plan stored on
 * the organization. Returns null when there is no workspace row, so anonymous
 * buckets stay on the free ceiling. Unit tests that never open a database
 * skip the lookup and keep using `setOrgPlan`.
 */
async function planFor(orgId: OrgId): Promise<PlanId> {
  const recorded = planByOrg.get(orgId);
  const lookedUp = await lookupWorkspacePlan(orgId);
  return lookedUp ?? recorded ?? "free";
}

async function lookupWorkspacePlan(orgId: OrgId): Promise<PlanId | null> {
  const { peekDb } = await import("@/server/db/client");
  const databaseReady =
    peekDb() !== null ||
    Boolean(process.env.TASKFLOW_DB_PATH) ||
    process.env.NODE_ENV !== "test";
  if (!databaseReady) return null;

  const { findOrgById } = await import(
    "@/server/repositories/organization-repository"
  );
  const org = await findOrgById(orgId);
  return org?.plan ?? null;
}

async function configFor(
  orgId: OrgId,
  bucketKey: string,
): Promise<RateLimitConfig> {
  const base = getBucketConfig(bucketKey);
  const plan = await planFor(orgId);
  const hourly = getPlanLimits(plan).apiRequestsPerHour;
  const factor = Number.isFinite(hourly) ? Math.max(1, hourly / 100) : 100;

  return {
    capacity: Math.min(base.capacity * factor, base.capacity * 100),
    refillPerMinute: Math.min(
      base.refillPerMinute * factor,
      base.refillPerMinute * 100,
    ),
  };
}

