const config = await configFor(orgId, bucketKey);
const key = `${orgId}:${bucketKey}`;
const nowMs = Date.now();

const state = buckets.get(key) ?? {
  tokens: config.capacity,
  updatedAt: nowMs,
  capacity: config.capacity,
};
const elapsedMinutes = (nowMs - state.updatedAt) / 60_000;
// A plan change takes effect on the next spend: growth grants the extra
// capacity immediately, and a downgrade caps the bucket at the new ceiling.
const grown = Math.max(0, config.capacity - state.capacity);
const tokens = Math.min(
  config.capacity,
  state.tokens + grown + elapsedMinutes * config.refillPerMinute,
);

const allowed = tokens >= cost;
const remaining = allowed ? tokens - cost : tokens;
buckets.set(key, {
  tokens: remaining,
  updatedAt: nowMs,
  capacity: config.capacity,
});

